select throws_ok($$select pcm.sso_pcm_gerar_visita('16660000-0000-0000-0000-000000000101','16660000-0000-0000-0000-00000000000a','16660000-0000-0000-0000-000000000020','16660000-0000-0000-0000-000000000021','2026-10-05','16660000-0000-0000-0000-000000000022','2026-10-09 08:00+00',null,'Fonte diferente')$$,'23505',null,'request reutilizado com payload alterado é recusado');
